WITH metrics AS (SELECT *, ROUND(amount / SUM(amount) OVER (PARTITION BY order_id, status), 4) AS amount_share, NTILE(3) OVER (PARTITION BY order_id ORDER BY amount DESC, id) AS amount_bucket FROM payments) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, CASE WHEN amount >= 1270 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, ROUND(SUM(amount_bucket) / NULLIF(COUNT(CASE WHEN method = 'card' THEN 1 END), 0), 2) AS amount_bucket_per_card, MIN(paid_at) AS first_paid_at, ROUND(AVG(amount), 2) AS avg_amount FROM metrics GROUP BY year_start, amount_tier
